const $=s=>document.querySelector(s);const names={wellness:'Health & wellbeing',rentals:'Rental services',careers:'Job opportunities'};let filter='all',status='active',tasks=[],storageOK=true;const key='velora-workbridge-steps-v1';
try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))tasks=saved.filter(t=>t&&typeof t.id==='string'&&typeof t.title==='string'&&names[t.category]&&typeof t.done==='boolean').map(t=>({...t,title:t.title.slice(0,120)}));}catch{storageOK=false;}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}function save(){try{localStorage.setItem(key,JSON.stringify(tasks));}catch{storageOK=false;toast('Storage is unavailable. Steps will last only for this visit.');}}
function render(){const scoped=tasks.filter(t=>filter==='all'||t.category===filter);$('#todo-count').textContent=scoped.filter(t=>!t.done).length;$('#done-count').textContent=scoped.filter(t=>t.done).length;const visible=scoped.filter(t=>t.done===(status==='done'));$('#tasks').replaceChildren();visible.forEach(t=>{const li=document.createElement('li');li.className='task-row'+(t.done?' completed':'');const check=document.createElement('button');check.className='task-check'+(t.done?' done':'');check.innerHTML='<svg aria-hidden="true"><use href="#check"/></svg>';check.setAttribute('aria-label',(t.done?'Restore step: ':'Complete step: ')+t.title);check.onclick=()=>{t.done=!t.done;save();render();toast(t.done?'Step completed. A little progress, beautifully made.':'Step moved back to your list.');};const details=document.createElement('div');details.className='task-details';const title=document.createElement('span');title.className='task-title';title.textContent=t.title;const cat=document.createElement('span');cat.className='task-category';cat.textContent=names[t.category];details.append(title,cat);const del=document.createElement('button');del.className='task-delete';del.textContent='×';del.setAttribute('aria-label','Delete step: '+t.title);del.onclick=()=>{tasks=tasks.filter(x=>x.id!==t.id);save();render();toast('Step removed.');};li.append(check,details,del);$('#tasks').append(li);});$('#empty').hidden=visible.length>0;$('#empty h3').textContent=status==='done'?'Your progress will feel good here.':'A fresh start, at your own pace.';$('#empty p').textContent=status==='done'?'Completed steps appear here when you check them off.':'Add a step, like “Prepare my résumé” or “Explore self-care.”';$('#first-task').hidden=status==='done';$('.task-foot>span:first-child').textContent=storageOK?'● Saved on this device':'● Storage unavailable — this visit only';}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(n=>{n.classList.toggle('active',n===b);n.setAttribute('aria-pressed',n===b?'true':'false');});$('#crumb').textContent=filter==='all'?'Overview':names[filter];document.querySelectorAll('[data-category]').forEach(c=>c.hidden=filter!=='all'&&c.dataset.category!==filter);$('#service-count').textContent=filter==='all'?'03 CONNECTED SERVICES':'01 CONNECTED SERVICE';render();});document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{status=b.dataset.status;document.querySelectorAll('[data-status]').forEach(n=>{n.classList.toggle('selected',n===b);n.setAttribute('aria-pressed',n===b?'true':'false');});render();});
function add(){ $('#task-form').reset();$('#task-category').value=filter==='all'?'wellness':filter;$('#task-dialog').showModal();$('#task-title').focus();}$('#add-task').onclick=add;$('#first-task').onclick=add;$('#task-form').onsubmit=e=>{e.preventDefault();const title=$('#task-title').value.trim();if(!title){$('#task-title').setCustomValidity('Please enter your next step.');$('#task-title').reportValidity();return;}tasks.push({id:globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2),title,category:$('#task-category').value,done:false});status='active';document.querySelectorAll('[data-status]').forEach(n=>n.classList.toggle('selected',n.dataset.status===status));save();render();$('#task-dialog').close();toast('Your next step is ready.');};$('#task-title').oninput=()=>$('#task-title').setCustomValidity('');
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));$('#how-it-works').onclick=()=>$('#help-dialog').showModal();document.querySelectorAll('.install').forEach(b=>b.onclick=()=>$('#install-dialog').showModal());let promptEvent;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();promptEvent=e;$('#native-install').hidden=false;});$('#native-install').onclick=async()=>{if(!promptEvent)return;await promptEvent.prompt();const choice=await promptEvent.userChoice;promptEvent=null;$('#native-install').hidden=true;if(choice.outcome==='accepted'){$('#install-dialog').close();toast('Your app installation has started.');}};window.addEventListener('appinstalled',()=>{$('#native-install').hidden=true;promptEvent=null;toast('VELORA–WORKBRIDGE is installed.');});$('#date').textContent=new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric'}).format(new Date());render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
